e answer => +      (DistanceCalculus.rightPlacedMeasurement +        (ιA := setting.ExpandedLocalSpace .alice) +        ((answerMeasurement lines .bob +          (.dline, directLdMap P.extendedDirectLd .dline sample)).postprocess +            (diagonalGameRead sample))).effect answer) +    (pairState setting) + +/-- The point/point read defect is unchanged when the jointly uniform direct +sample's unused index and direction are retained. -/ +private theorem point_read_defect_on_direct_samples_eq_rejection +    (lines : ExtendedLinesWitness setting points deltaL) : +    consistencyDefect (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +        (fun sample answer => heteroKron +          (((answerMeasurement lines .alice +            (.point, directLdMap P.extendedDirectLd .point sample)).postprocess +              pointGameRead).effect answer) 1) +        (fun sample answer => heteroKron 1 +          (((answerMeasurement lines .bob +            (.point, directLdMap P.extendedDirectLd .point sample)).postprocess +              pointGameRead).effect answer)) +        (pairState setting) = +      directLdBranchRejectionProbability P.extendedDirectLd (strategy lines) +        (.point, .point) := by +  rw [point_branch_rejection_eq_consistencyDefect lines] +  calc +    _ = consistencyDefect (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +        (fun sample answer => heteroKron +          (((points.Q .alice +            (projX (directPointToPauli P sample.point)) +            (projZ (directPointToPauli P sample.point))).postprocess fun values => +              some (directPointToPauli P sample.point (alphaVar P.m) * values.1 + +                directPointToPauli P sample.point (betaVar P.m) * values.2)).effect answer) 1) +        (fun sample answer => heteroKron 1 +          (((points.Q .bob +            (projX (directPointToPauli P sample.point)) +            (projZ (directPointToPauli P sample.point))).postprocess fun values => +              some (directPointToPauli P sample.point (alphaVar P.m) * values.1 + +                directPointToPauli P sample.point (betaVar P.m) * values.2)).effect answer)) +        (pairState setting) := by +      apply consistencyDefect_congr <;> intro sample answer +      · rw [point_read_effect lines .alice] +      · rw [point_read_effect lines .bob] +    _ = consistencyDefect (uniformDistribution +          (Fin P.extendedDirectLd.m → DirectScalarQ P.extendedDirectLd)) +        (fun point answer => heteroKron +          (((points.Q .alice +            (projX (directPointToPauli P point)) +            (projZ (directPointToPauli P point))).postprocess fun values => +              some (directPointToPauli P point (alphaVar P.m) * values.1 + +                directPointToPauli P point (betaVar P.m) * values.2)).effect answer) 1) +        (fun point answer => heteroKron 1 +          (((points.Q .bob +            (projX (directPointToPauli P point)) +            (projZ (directPointToPauli P point))).postprocess fun values => +              some (directPointToPauli P point (alphaVar P.m) * values.1 + +                directPointToPauli P point (betaVar P.m) * values.2)).effect answer)) +        (pairState setting) := by +      exact consistencyDefect_uniform_equiv_fst +        (Gamma := DirectLdSpace P.extendedDirectLd) +        (X := Fin P.extendedDirectLd.m → DirectScalarQ P.extendedDirectLd) +        (Y := Fin P.extendedDirectLd.m × +          (Fin P.extendedDirectLd.m → DirectScalarQ P.extendedDirectLd)) +        (Alpha := Option (PauliScalar P)) +        (I := setting.ExpandedLocalSpace .alice × setting.ExpandedLocalSpace .bob) +        (directSamplePointEquiv P.extendedDirectLd) +        (fun point answer => heteroKron +          (((points.Q .alice +            (projX (directPointToPauli P point)) +            (projZ (directPointToPauli P point))).postprocess fun values => +              some (directPointToPauli P point (alphaVar P.m) * values.1 + +                directPointToPau