an @@ -0,0 +1,325 @@ +import MIPStarRE.QPBT.Combining.ExtendedLineGame.EvaluatedLineComparison + +/-! +# Failed completed line-evaluation mass + +This module bounds the marginal Born mass of the `none` outcome of each +completed line read by the corresponding mixed line/point rejection branch. +Wrong-format point answers also read as `none`, so the proof first removes +those answer pairs using their zero Born weight and only then applies event +inclusion. + +These statements concern completed `Option`-valued readouts. They do not +identify successful parameter evaluation or prove a coefficient-collision +bound. + +## References + +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1288` +- `references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:232-248` +- Blueprint `lem:qld-4-7`. +- Issue #332. +-/ + +open scoped BigOperators MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +namespace ExtendedLineGame + +variable {P : AdmissibleParams} {epsilon deltaQ deltaL : ℝ} +variable {setting : ProjectiveSetting P epsilon} +variable {points : CombinedPointsWitness setting deltaQ} + +/-- A direct point answer has completed read `none` exactly when its answer +tag is invalid for a point question. -/ +private theorem pointGameRead_eq_none_iff_invalid +    (answer : DirectLdAnswer P.extendedDirectLd) : +    pointGameRead answer = none ↔ +      validDirectLdAnswer (D := P.extendedDirectLd) .point answer = false := by +  cases answer <;> simp [pointGameRead, validDirectLdAnswer] + +/-- After zero-weight invalid point answers are removed, Alice's line-`none` +event is the event that the line read is `none` and the point read is not. -/ +private theorem alice_line_none_event_eq_point_some +    (lines : ExtendedLinesWitness setting points deltaL) +    (kind : LdType) (sample : DirectLdSpace P.extendedDirectLd) +    (readLine : DirectLdAnswer P.extendedDirectLd → Option (