on (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) := by +        apply avgOver_congr +        intro t +        congr 2 +        rw [hdirection, hbase] +        have hadd : (Equiv.addRight (-r)).symm t = t + r := by +          simp +        rw [hadd] +        change lineRepMap direction sample.point + (t + r) • direction = +          sample.point + t • direction +        rw [add_comm t r, add_smul, ← add_assoc, +          ← directLineRepParameter_spec direction sample.point] +  have hsample : ∀ t : DirectScalarQ D, +      avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) = +        avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, sample.point)) := by +    intro t +    calc +      avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) = +          avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +            F (lineOf ((directLdSpacePointTranslateEquiv D directionOf t).symm sample), +              ((directLdSpacePointTranslateEquiv D directionOf t).symm sample).point + +                t • directionOf +                  ((directLdSpacePointTranslateEquiv D directionOf t).symm sample).index +                  ((directLdSpacePointTranslateEquiv D directionOf t).symm sample).direction)) := +        avgOver_uniform_equiv (directLdSpacePointTranslateEquiv D directionOf t) _ +      _ = avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, sample.point)) := by +        apply avgOver_congr +        intro sample +        congr 2 +        · change lineOf (directLdSpacePointTranslateEquiv D directionOf (-t) sample) = +           